fault_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/9a28bf25c23c/fault.log 2>&1
echo FAULT_BEFORE $(date -u +%s)
systemctl stop nginx
test "$(systemctl is-active nginx)" = inactive
echo FAULT_VERIFIED $(date -u +%s)

rollback_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/9a28bf25c23c/rollback.log 2>&1
echo ROLLBACK_BEFORE $(date -u +%s)
systemctl start nginx
echo ROLLBACK_AFTER $(date -u +%s)
